// DEMO DATA. Two rover missions built from street-following routes (mock-route.json, generated by
// scripts/build_mock_route.mjs). Sites sit at intersection-level points and are labelled by neighbourhood only;
// none of them describes a real property.
import route from './mock-route.json' with {type: 'json'};
import {bearingDeg, distanceM} from './track.ts';
import type {Hazard, LngLat, Mission, ReportStatus, Site, SiteStatus, TelemetryPoint} from './types.ts';

const SAMPLE_MS = 2000; // telemetry rate of the simulated rover
const MIN = 60_000;

interface SitePlan {
  stop: number;            // index into the route's stops (a waypoint)
  area: string;
  status: Exclude<SiteStatus, 'pending' | 'inspecting'>;
  dwellMin: number;
  hazards: Hazard[];
  reportStatus: ReportStatus;
}

interface MissionPlan {
  id: string; roverId: string; color: string;
  start: number; durationMs: number; batteryUse: number;
  sites: SitePlan[];
}

// Deterministic 0–1 noise so the demo is identical on every load.
const noise = (i: number) => { const x = Math.sin(i * 12.9898 + 78.233) * 43758.5453; return x - Math.floor(x); };

// Both routes are loops: each rover leaves its base, inspects its sites, and drives back to the base.
const PLANS: MissionPlan[] = [
  {
    id: 'M-1017-A', roverId: 'ROVER-01', color: '#F25C24',
    start: Date.UTC(2026, 9, 17, 17, 5, 0), // 13:05 Toronto (EDT)
    durationMs: (1 * 3600 + 42 * 60 + 30) * 1000, batteryUse: 26,
    sites: [
      {stop: 1, area: 'King West', status: 'cleared', dwellMin: 11, reportStatus: 'submitted', hazards: []},
      {stop: 2, area: 'Niagara', status: 'hazards', dwellMin: 14, reportStatus: 'awaiting_confirmation', hazards: [
        {type: 'Water damage', confidence: 'high', note: 'Staining and sagging on rear ceiling plane'},
        {type: 'Blocked exit', confidence: 'medium', note: 'Debris pile against secondary door'},
      ]},
      {stop: 3, area: 'Liberty Village', status: 'failed', dwellMin: 7, reportStatus: 'draft', hazards: []},
      {stop: 4, area: 'Garrison Common', status: 'hazards', dwellMin: 13, reportStatus: 'draft', hazards: [
        {type: 'Structural concern', confidence: 'high', note: 'Front wall out of plumb in LiDAR section'},
        {type: 'Exposed wiring', confidence: 'medium'},
        {type: 'Missing smoke alarm', confidence: 'low', note: 'No detector visible in scanned rooms'},
      ]},
      {stop: 5, area: 'Fort York', status: 'cleared', dwellMin: 10, reportStatus: 'submitted', hazards: []},
    ],
  },
  {
    id: 'M-1017-B', roverId: 'ROVER-02', color: '#6A5ACD',
    start: Date.UTC(2026, 9, 17, 17, 40, 0), // 13:40 Toronto
    durationMs: 38 * MIN, batteryUse: 12,
    sites: [
      {stop: 1, area: 'Harbourfront', status: 'cleared', dwellMin: 12, reportStatus: 'draft', hazards: []},
    ],
  },
];

function buildMission(plan: MissionPlan, siteOffset: number): Mission {
  const {coords, stops} = route.routes[plan.roverId as keyof typeof route.routes] as unknown as {coords: LngLat[]; stops: {index: number}[]};
  const dwellAt = new Map(plan.sites.map(s => [stops[s.stop].index, s.dwellMin * MIN]));
  const dwellTotal = plan.sites.reduce((sum, s) => sum + s.dwellMin * MIN, 0);

  // Per-segment speed factor (0.8–1.2), then solve the base speed so the mission lasts exactly durationMs.
  const segs = coords.slice(1).map((c, i) => ({len: distanceM(coords[i], c), factor: 0.8 + 0.4 * noise(i)}));
  const base = segs.reduce((s, g) => s + g.len / g.factor, 0) / ((plan.durationMs - dwellTotal) / 1000);

  // Keyframes: time at every vertex, with a repeated vertex for each dwell.
  const keys: {t: number; coord: LngLat; heading: number; speed: number}[] = [];
  const arrivals = new Map<number, number>();
  let t = plan.start, heading = bearingDeg(coords[0], coords[1]);
  keys.push({t, coord: coords[0], heading, speed: 0});
  segs.forEach((g, i) => {
    const speed = base * g.factor;
    heading = g.len > 0.5 ? bearingDeg(coords[i], coords[i + 1]) : heading;
    t += g.len / speed * 1000;
    keys.push({t, coord: coords[i + 1], heading, speed});
    const dwell = dwellAt.get(i + 1);
    if (dwell) { arrivals.set(i + 1, t); t += dwell; keys.push({t, coord: coords[i + 1], heading, speed: 0}); }
  });

  // Resample keyframes at the telemetry rate.
  const track: TelemetryPoint[] = [];
  const end = keys[keys.length - 1].t;
  for (let k = 0, now = plan.start; ; now = Math.min(now + SAMPLE_MS, end)) {
    while (k < keys.length - 2 && keys[k + 1].t <= now) k++;
    const a = keys[k], b = keys[k + 1] ?? a;
    const f = b.t > a.t ? Math.min(1, (now - a.t) / (b.t - a.t)) : 1;
    track.push({
      t: Math.round(now),
      coord: [a.coord[0] + (b.coord[0] - a.coord[0]) * f, a.coord[1] + (b.coord[1] - a.coord[1]) * f],
      heading: Math.round(b.heading * 10) / 10,
      speed: Math.round(b.speed * 100) / 100,
      batteryPct: Math.round((100 - plan.batteryUse * (now - plan.start) / plan.durationMs) * 10) / 10,
      // Slowly wandering link quality (55–95%) with occasional dips, as between tall buildings.
      signalPct: Math.round(75 + 15 * Math.sin((now - plan.start) / 410_000) + 8 * Math.sin((now - plan.start) / 97_000) - (noise(Math.floor((now - plan.start) / 60_000)) > 0.9 ? 25 : 0)),
    });
    if (end - now < 1) break; // within rounding of the end: this point is the final one
  }

  const sites: Site[] = plan.sites.map((s, i) => {
    const n = String(siteOffset + i + 1).padStart(2, '0');
    const arrivedAt = Math.round(arrivals.get(stops[s.stop].index)!);
    return {
      id: `SITE-${n}`, label: `SITE ${n}`, area: s.area, coord: coords[stops[s.stop].index],
      status: s.status, arrivedAt, departedAt: arrivedAt + s.dwellMin * MIN,
      hazards: s.hazards, reportStatus: s.reportStatus,
    };
  });

  return {
    id: plan.id, roverId: plan.roverId, color: plan.color, startedAt: plan.start, endedAt: Math.round(end),
    track, plannedRoute: coords, sites,
  };
}

let offset = 0;
export const MOCK_MISSIONS: Mission[] = PLANS.map(plan => {
  const mission = buildMission(plan, offset);
  offset += plan.sites.length;
  return mission;
});
